"""Random word lists of varying length, including empty and single-element
lists."""

import string

WORDS = ["red", "blue", "north", "south", "up", "down", "east", "west",
         "one", "two", "alpha", "beta", "x", "y9", "q"]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.choice([0, 1, rng.randint(2, 8)])
    items = [rng.choice(WORDS) for _ in range(n)]
    lines = [str(n)] + items
    return {"name": "a %d-element list #%d" % (n, index),
            "stdin": "\n".join(lines) + "\n"}
